const results = await Promise.allSettled([
  tools.exec_command({cmd:"pwd && git status --short --branch && git remote -v && rg --files -g 'AGENTS.md' -g 'composer.json' -g '.github/workflows/*' -g '*phpunit*' -g '*phpstan*' -g 'renovate*' -g '.renovate*'","max_output_tokens":5000}),
  tools.exec_command({cmd:"cat /Users/ab/.agents/skills/find-docs/SKILL.md","max_output_tokens":8000}),
  tools.exec_command({cmd:"gh repo view k-kinzal/php-ai-toolkit --json nameWithOwner,defaultBranchRef,url && gh run list --repo k-kinzal/php-ai-toolkit --branch main --limit 12 --json databaseId,name,headSha,status,conclusion,event,createdAt,url && gh pr list --repo k-kinzal/php-ai-toolkit --state open --json number,title,headRefName,baseRefName,author,mergeable,mergeStateStatus,statusCheckRollup,url","max_output_tokens":10000})
]); results.forEach((r,i)=>text({i,...r}));

const results = await Promise.allSettled([
  tools.exec_command({cmd:"git fetch origin main && git rev-list --left-right --count main...origin/main && git log -1 --format='%H %s' main && git log --oneline origin/main..main && git diff --shortstat && git ls-files --others --exclude-standard | wc -l && cat AGENTS.md","max_output_tokens":3000}),
  tools.exec_command({cmd:"gh api repos/k-kinzal/php-ai-toolkit/commits/main/check-runs --jq '.check_runs[] | {name,status,conclusion,html_url}' && gh api repos/k-kinzal/php-ai-toolkit/commits/main/status --jq '{state,sha,statuses:[.statuses[]|{context,state,target_url}]}' && gh pr list --repo k-kinzal/php-ai-toolkit --state open --limit 100 --json number,title,author,headRefName,url","max_output_tokens":6000})
]); results.forEach((r,i)=>text({i,...r}));

